head.script:
scwin.screenId = "jldods70207";

///////// 1. 변수 및 선언 영역 /////////

scwin.disclsAlertMsg = $c.util.getComponent('disclsAlertMsg');

scwin.disclsCellphoneAhthErr = $c.util.getComponent('disclsCellphoneAhthErr');

scwin.discls_minute = 4;

scwin.discls_second = 59;

scwin.discls_timer = undefined;


///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_kclicUsrTpId", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "kclicUsrTpId" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("kclicUsrTpId")) === 'LIST_CORP_DISCLS'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_sPw", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("sPw")))); } },
        { childId: "ipt_sPwConfirm", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("sPwConfirm")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.alertDiscls("인증번호가 발송되었습니다.");
        scwin.startTimer2();
        (document.disclsConfirm || { elements: [] }).action = "/combasinfo/comOvrvw.do?method=disclsConfirmInputPop&confrimChk=ok";
        const p = {}; p["returnValue"] = $c.util.getComponent("ipt_returnValue").getValue(); p["sPw"] = $c.util.getComponent("ipt_sPw").getValue(); p["sPwConfirm"] = $c.util.getComponent("ipt_sPwConfirm").getValue(); p["chrgTpCd"] = $c.util.getComponent("dma_closeCellphoneAhthReq").get("chrgTpCd"); p["phonePw"] = $c.util.getComponent("ipt_phonePw").getValue(); $c.win.setPageFrameSrc($c.win.getFrame(), '/jldods70207/jldods70207.xml', p);
        scwin.alertDiscls("휴대폰 인증에 실패하였습니다.\n다시 시도하십시오.");
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70207.onpageload' }); }
};

// [A] 초기 목록 미해결 — 같은 액션인데 method 가 4개다(comovrvw#disclsconfirminputpop vs comovrvw#excelpop vs comovrvw#cellphoneahthsend vs comovrvw#disclspasswordchange) — 어느 것이 «열자마자» 인지 정할 근거가 없다


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods70207.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

