/**
 * @method
 * @name scwin.tx_closeCellphoneAhth
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_closeCellphoneAhth = async function () {
    const sbmOptions = {
        id: "tx_closeCellphoneAhth",
        method: "post",
        action: "/combasinfo/comOvrvw.do?method=disclsConfirmAdjPop",
        ref: "dma_closeCellphoneAhthReq",
        target: "dlt_disclsUserList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldods70207.tx_closeCellphoneAhth" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

