*/
scwin.alertDiscls = function (msg) {
    /* sdd-asis-lifecycle:begin alertDiscls — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    layerUI2('#layerUi');
    layerUI2('.layerUi');
    $('#txt_pAlertDisclsText')[0].innerText = msg;
    scwin.disclsAlertMsg.setStyle("display", "");
    /* sdd-asis-lifecycle:end */
};


